macro_rules! AsyncSeek {
    () => {
        # [doc = " Seek bytes asynchronously."] # [doc = ""] # [doc = " This trait is analogous to the [`std::io::Seek`] trait, but integrates"] # [doc = " with the asynchronous task system. In particular, the `start_seek`"] # [doc = " method, unlike [`Seek::seek`], will not block the calling thread."] # [doc = ""] # [doc = " Utilities for working with `AsyncSeek` values are provided by"] # [doc = " [`AsyncSeekExt`]."] # [doc = ""] # [doc = " [`std::io::Seek`]: std::io::Seek"] # [doc = " [`Seek::seek`]: std::io::Seek::seek()"] # [doc = " [`AsyncSeekExt`]: crate::io::AsyncSeekExt"] pub trait AsyncSeek { # [doc = " Attempts to seek to an offset, in bytes, in a stream."] # [doc = ""] # [doc = " A seek beyond the end of a stream is allowed, but behavior is defined"] # [doc = " by the implementation."] # [doc = ""] # [doc = " If this function returns successfully, then the job has been submitted."] # [doc = " To find out when it completes, call `poll_complete`."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This function can return [`io::ErrorKind::Other`] in case there is"] # [doc = " another seek in progress. To avoid this, it is advisable that any call"] # [doc = " to `start_seek` is preceded by a call to `poll_complete` to ensure all"] # [doc = " pending seeks have completed."] fn start_seek (self : Pin < & mut Self > , position : SeekFrom) -> io :: Result < () > ; # [doc = " Waits for a seek operation to complete."] # [doc = ""] # [doc = " If the seek operation completed successfully, this method returns the"] # [doc = " new position from the start of the stream. That position can be used"] # [doc = " later with [`SeekFrom::Start`]."] # [doc = ""] # [doc = " The position returned by calling this method can only be relied on right"] # [doc = " after `start_seek`. If you have changed the position by e.g. reading or"] # [doc = " writing since calling `start_seek`, then it is unspecified whether the"] # [doc = " returned position takes that position change into account. Similarly, if"] # [doc = " `start_seek` has never been called, then it is unspecified whether"] # [doc = " `poll_complete` returns the actual position or some other placeholder"] # [doc = " value (such as 0)."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " Seeking to a negative offset is considered an error."] fn poll_complete (self : Pin < & mut Self > , cx : & mut Context < '_ >) -> Poll < io :: Result < u64 > > ; }
    };
}

AsyncSeek!()